<style>.project-client-option{display:flex;align-items:center;gap:8px}.project-client-option img{width:28px;height:28px;object-fit:contain;border-radius:7px;background:#f1f5f9}.select2-results__option{padding:7px 10px}.select2-container--default .select2-selection--single{height:44px;border-radius:10px;border-color:#cbd5e1}.select2-container--default .select2-selection--single .select2-selection__rendered{line-height:42px}</style><script>window.setTimeout(()=>{const select=document.querySelector('#projectDialog select[name="client_id"]');if(!select||!window.jQuery||!jQuery.fn.select2)return;const logos=<?=json_encode($clientLogoMap,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;Array.from(select.options).forEach(option=>{if(logos[option.value])option.dataset.logo='../uploads/logos_clients/'+logos[option.value];});jQuery(select).select2({dropdownParent:jQuery('#projectDialog'),placeholder:'Rechercher par client ou NCC...',allowClear:true,width:'100%',templateResult:item=>{if(!item.id)return item.text;const logo=item.element?.dataset?.logo;const node=jQuery('<span class="project-client-option"><span></span></span>');if(logo)node.prepend(jQuery('<img>').attr({src:logo,alt:''}));node.find('span').text(item.text);return node;},templateSelection:item=>{if(!item.id)return item.text;const logo=item.element?.dataset?.logo;const node=jQuery('<span class="project-client-option"><span></span></span>');if(logo)node.prepend(jQuery('<img>').attr({src:logo,alt:''}));node.find('span').text(item.text);return node;}});},0);</script>
<script>if(new URLSearchParams(location.search).has('create')){document.getElementById('projectDialog')?.close();}</script>
